H(186,4,"PIM — configurações de função","\"On activation, require Azure MFA\" = Yes: User1 precisa de MFA (Sim). Não há aprovação exigida (Não). O Privileged Authentication Administrator gerencia métodos de autenticação, **não** atribuições de função, então a afirmação sobre User2 **e** User3 é falsa (Não).",
  yn=("User1 requires Azure Multi-Factor Authentication (MFA) to activate the Global administrator role.","User2 must approve all activation requests for the Global administrator role.","User2 and User3 can edit the Global administrator role assignment."), ans="YNN")
H(189,4,"Access reviews","User1 está no Group1, que é membro do Group3. A revisão de grupo vale para membros **diretos** do Group3, então User1 não é removido do Group1 (Não). User2 nem é membro do Group3; além disso, o Group2 é sincronizado do AD, e a revisão não remove membros de grupos on-premises (Não). User3 não é membro do Group2 (Não). O dump marcava Sim na segunda.",
  yn=("User1 will be removed automatically from Group 1 if the user does not respond to the review request.","User 2 will be removed automatically from Group 3 if the user does not respond to the review request.","User 3 will be removed automatically from Group 2 if the user does not respond to the review"), ans="NNN", ans_orig="NYN", r="corrigida")
H(191,4,"Licenciamento de access reviews","Precisa de licença (P2/ID Governance) cada usuário **membro** que se autorrevisa ou atua como revisor. Group1 (auto-revisão de todos): **500** internos. Guests são cobertos pelo modelo MAU do External ID e não exigem licença por usuário. Group2 (o dono revisa os guests): **1** licença, a do dono. O dump marcava 525 para o Group1.",
  slots=[("Group1:","1|500|525",1),("Group2:","1|100|295|395",0)], ans_orig=[2,0], r="corrigida")
H(192,4,"Entitlement management — ciclo de vida de externos","Guest1 e Guest2 entraram pelo access package. Quando a atribuição expira (1º de abril), eles são bloqueados e removidos 30 dias depois, antes de 5 de maio (a função de diretório não impede a remoção). Guest3 foi convidado diretamente, fora do access package, então a regra não se aplica e ele continua no tenant.",
  yn=("On May 5, 2022, the Guest1 account is in contoso.com.","On May 5, 2022, the Guest2 account is in contoso.com.","On May 5, 2022, the Guest3 account is in contoso.com."), ans="NNY",
  fix={"30 On March 11, 2.022, you create":"30\n\nOn February 28, 2022, you create","Resource rales":"Resource roles"})
H(195,4,"PIM — aprovação e duração","User1 recebeu atribuição **elegível**, não ativa, e precisa ativar com aprovação (Não). O Group1 (User2 e User3) aprova, mas ninguém aprova a própria solicitação, então só o User3 pode aprovar a do User2 (Sim). A ativação nunca passa do fim da atribuição elegível (31/01 23:59), então o User1 não usa a função até 04:00 de 1º/02 (Não). O dump marcava Não/Não/Sim; a comunidade diverge na terceira.",
  yn=("User1 is assigned the Application administrator role automatically.","When User2 requests to be assigned the Application administrator role, only User3 can approve the request.","If a request by User1 to be assigned the Application administrator role is approved on January 31, 2021, at 23:00, User1 can use the role until February 1, 2021, at 04:00."), ans="NYN", ans_orig="NNY", r="duvidosa")
H(196,4,"Access reviews — configurações","Para remover automaticamente quem não responde, altere **If reviewers don't respond** para *Remove access* (o Auto apply já está habilitado). O gabarito também aponta **Reviewers** (Members/self) como a outra configuração a ajustar.",
  panel=("Access review settings","Reviewers|Auto apply results to resource|If reviewers don't respond|Action to apply on denied guest users|At end of review, send notification to|Show recommendations|Require reason on approval|Mail notifications|Reminders|Additional content for reviewer email","0,2"))
